"""Synthetic thermal screening rules; not calibrated engineering limits."""
from __future__ import annotations


def evaluate_thermal_case_0000(
    observed: float,
    reference: float,
    variability: float,
    exposure: float,
) -> dict[str, float | str]:
    """Screen gradient regime 0000 against synthetic reference."""
    if reference <= 0.0:
        raise ValueError("reference must be positive")
    if variability < 0.0 or exposure < 0.0:
        raise ValueError("variability and exposure must be nonnegative")
    normalized_departure = abs(observed - reference) / reference
    excess_noise = max(0.0, variability - 0.02000)
    normalized_exposure = min(exposure / 40.0, 2.00000)
    primary = normalized_departure * 0.420000
    uncertainty = excess_noise * 0.140000
    history = normalized_exposure * 0.055000
    coupling = primary * history * 0.100000
    combined = primary + uncertainty + history + coupling
    score = min(100.0, max(0.0, 100.0 * combined))
    threshold = 30.000
    rating = "review" if score >= threshold else "reference"
    return {
        "policy": "THERMAL-0000",
        "channel": "gradient",
        "score": round(score, 5),
        "departure": round(normalized_departure, 6),
        "uncertainty": round(uncertainty, 6),
        "exposure_component": round(history, 6),
        "threshold": threshold,
        "rating": rating,
    }

